      elseif(in_array($op,['note_add','note_edit','note_delete'],true)){$l=&library($d,$libId);$scope=(string)$_POST['scope'];if($scope==='library')$notes=&$l['notes'];elseif($scope==='day'){$date=(string)$_POST['date'];if($date<$l['start_date']||$date>gmdate('Y-m-d'))fail('Invalid note date.');$l['day_notes'][$date]??=[];$notes=&$l['day_notes'][$date];}elseif($scope==='wound'){$w=&wound($l,(string)$_POST['wound_id']);$notes=&$w['notes'];}else fail('Invalid note scope.');$nid=(string)($_POST['note_id']??'');if($op==='note_add'){$text=trim((string)$_POST['text']);if($text==='')fail('Note cannot be empty.');$notes[]=['id'=>new_id('note'),'text'=>$text,'created_at'=>now()];}else{$found=null;foreach($notes as $i=>$n)if($n['id']===$nid)$found=$i;if($found===null)fail('Note not found.',404);if($op==='note_delete')array_splice($notes,$found,1);else{$text=trim((string)$_POST['text']);if($text==='')fail('Note cannot be empty.');$notes[$found]['text']=$text;$notes[$found]['updated_at']=now();}}$l['revision']++;$redirect.='&library='.$libId.(isset($date)?'&date='.$date:'');}
      elseif(in_array($op,['placeholder','upload'],true)){$l=&library($d,$libId);$w=&wound($l,(string)$_POST['wound_id']);$date=(string)$_POST['date'];if(!isset($w['updates'][$date]))fail('Create the wound update first.');$id=new_id('photo');$order=count($w['updates'][$date]['photos'])+1;$angle=trim((string)($_POST['angle']??'Front'))?:'Front';$ext='svg';$mime='image/svg+xml';$content='';if($op==='placeholder'){$serial='IMG-'.strtoupper(bin2hex(random_bytes(3)));$content=placeholder($serial);}else{if(!isset($_FILES['photo'])||$_FILES['photo']['error']!==UPLOAD_ERR_OK)fail('Choose an image to upload.');if($_FILES['photo']['size']>MAX_UPLOAD)fail('Image exceeds the 15 MB limit.',413);$info=@getimagesize($_FILES['photo']['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!$info||!isset($types[$info['mime']]))fail('Upload must be a valid JPEG, PNG, or WebP image.');$mime=$info['mime'];$ext=$types[$mime];}$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($angle));$name=sprintf('%02d-%s-%s.%s',$order,trim($slug,'-')?:'angle',$id,$ext);$dir="$patientDir/libraries/$libId/wounds/{$w['id']}/$date";if(!is_dir($dir)&&!mkdir($dir,0770,true))fail('Could not create photo storage.',500);$path="$dir/$name";$ok=$op==='placeholder'?file_put_contents($path,$content)!==false:move_uploaded_file($_FILES['photo']['tmp_name'],$path);if(!$ok)fail('Could not store the image.',500);$w['updates'][$date]['photos'][]=['id'=>$id,'angle'=>$angle,'caption'=>trim((string)($_POST['caption']??'')),'created_at'=>now(),'sort_order'=>$order,'filename'=>$name,'mime'=>$mime,'bytes'=>filesize($path)];$l['revision']++;$redirect.='&library='.$libId.'&date='.$date;}
      elseif(in_array($op,['photo_edit','photo_delete','photo_move'],true)){$l=&library($d,$libId);$w=&wound($l,(string)$_POST['wound_id']);$date=(string)$_POST['date'];$photos=&$w['updates'][$date]['photos'];$pi=null;foreach($photos as $i=>$p)if($p['id']===(string)$_POST['photo_id'])$pi=$i;if($pi===null)fail('Photo not found.',404);$dir="$patientDir/libraries/$libId/wounds/{$w['id']}/$date";if($op==='photo_delete'){if(is_file("$dir/{$photos[$pi]['filename']}"))unlink("$dir/{$photos[$pi]['filename']}");array_splice($photos,$pi,1);}elseif($op==='photo_edit'){$photos[$pi]['angle']=trim((string)$_POST['angle'])?:'Unspecified';$photos[$pi]['caption']=trim((string)($_POST['caption']??''));}else{$to=$pi+((string)$_POST['direction']==='left'?-1:1);if(isset($photos[$to]))[$photos[$pi],$photos[$to]]=[$photos[$to],$photos[$pi]];}foreach($photos as $i=>&$p){$ext=pathinfo($p['filename'],PATHINFO_EXTENSION);$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower($p['angle'])),'-')?:'angle';$new=sprintf('%02d-%s-%s.%s',$i+1,$slug,$p['id'],$ext);if($new!==$p['filename']&&is_file("$dir/{$p['filename']}")){rename("$dir/{$p['filename']}","$dir/.tmp-{$p['id']}.$ext");$p['_new']=$new;}$p['sort_order']=$i+1;}unset($p);foreach($photos as &$p)if(isset($p['_new'])){$tmp="$dir/.tmp-{$p['id']}.".pathinfo($p['filename'],PATHINFO_EXTENSION);rename($tmp,"$dir/{$p['_new']}");$p['filename']=$p['_new'];unset($p['_new']);}unset($p);$l['revision']++;$redirect.='&library='.$libId.'&date='.$date;}
