<?php $active=array_filter($selected['wounds'],fn($w)=>$w['active']);$updated=0;foreach($active as $w)if(isset($w['updates'][$date]))$updated++;if(!$updated):?><div class="empty compact"><strong>No wound updates recorded</strong><span>This date remains intentionally blank until an update is added.</span></div><?php endif?><div class="wound-grid"><?php foreach($active as $w):$u=$w['updates'][$date]??null;?><article class="wound-card <?=$u?'':'missing'?> <?=count($w['notes'])?'noted':''?>"><div class="wound-title"><div><p class="state"><?=$u?'✓ Updated':'○ Not updated on this date'?></p><h3><?=h($w['name'])?></h3><small><?=h($w['location'])?></small></div><button class="ghost small" onclick="showModal('notes-<?=h($w['id'])?>')">Notes <?=count($w['notes'])?><span class="sr-only"><?=count($w['notes'])?> notes</span></button></div><?php if($u):?><p><?=h($u['note'])?:'<span class="muted">No update note</span>'?></p><?php if(!$u['photos']):?><div class="no-photo">No photos added</div><?php else:?><div class="gallery"><?php foreach($u['photos'] as $i=>$p):?><figure><img src="index.php?action=media&id=<?=h($p['id'])?>&v=<?=$selected['revision']?>" alt="<?=h($p['angle'])?> view of <?=h($w['name'])?>"><figcaption><strong><?=h($p['angle'])?></strong><small><?=h($p['caption'])?></small><div class="photo-actions"><form method="post"><?=hidden($csrf,$selectedId,$w['id'],$date)?><input type="hidden" name="op" value="photo_move"><input type="hidden" name="photo_id" value="<?=h($p['id'])?>"><button name="direction" value="left" aria-label="Move photo left" <?=$i===0?'disabled':''?>>←</button><button name="direction" value="right" aria-label="Move photo right" <?=$i===count($u['photos'])-1?'disabled':''?>>→</button></form><button onclick="showModal('photo-<?=h($p['id'])?>')">Edit</button></div></figcaption></figure><?php endforeach?></div><?php endif?><div class="row"><button onclick="showModal('photo-add-<?=h($w['id'])?>')">Add photo</button><button class="ghost" onclick="showModal('update-<?=h($w['id'])?>')">Edit update</button><form method="post" onsubmit="return confirm('Delete this date update and its photos?')"><?=hidden($csrf,$selectedId,$w['id'],$date)?><input type="hidden" name="op" value="update_delete"><button class="danger ghost">Delete update</button></form></div><?php else:?><button onclick="showModal('update-<?=h($w['id'])?>')">+ Add update for this date</button><?php endif?></article><?php endforeach?></div><div class="section-title"><h2>Wound list</h2><button class="ghost" onclick="showModal('wound-new')">+ Add wound</button></div><div class="manage-list"><?php foreach($selected['wounds'] as $w):?><div><span><strong><?=h($w['name'])?></strong><small><?=h($w['location'])?> · <?=$w['active']?'Active':'Inactive — history retained'?></small></span><span class="row"><button class="ghost small" onclick="showModal('wound-<?=h($w['id'])?>')">Edit</button><form method="post" onsubmit="return confirm('Delete this wound, its history, and photos?')"><?=hidden($csrf,$selectedId,$w['id'])?><input type="hidden" name="op" value="wound_delete"><button class="danger ghost small">Delete</button></form></span></div><?php endforeach?></div>
<?=modals($selected,$csrf,$date)?><?php endif?></section></div><?php endif?></main><footer>Demo wound-photo recordkeeping app — not for diagnosis or emergency use.</footer><script><?=js()?></script></body></html>
