function hidden(string $csrf,string $lib,string $w='',string $date=''):string{return '<input type="hidden" name="csrf" value="'.h($csrf).'"><input type="hidden" name="library_id" value="'.h($lib).'">'.($w?'<input type="hidden" name="wound_id" value="'.h($w).'">':'').($date?'<input type="hidden" name="date" value="'.h($date).'">':'');}
function sync_count(array $d):int{$n=0;foreach($d['libraries'] as $l)foreach($l['wounds'] as $w)foreach($w['updates'] as $u)$n+=count($u['photos']);return $n;}
function timeline(array $l,string $date):string{$start=new DateTimeImmutable($l['start_date']);$end=new DateTimeImmutable('today');$cur=new DateTimeImmutable($date);$month=$cur->format('Y-m');$first=maxdate($start,new DateTimeImmutable($month.'-01'));$last=mindate($end,new DateTimeImmutable($month.'-01 last day of this month'));$out='<nav class="timeline" aria-label="Date timeline"><div class="month-nav"><a href="?patient='.PATIENT_ID.'&library='.h($l['id']).'&date='.$cur->modify('-1 month')->format('Y-m-d').'">← Previous</a><strong>'.$cur->format('F Y').'</strong><a href="?patient='.PATIENT_ID.'&library='.h($l['id']).'&date='.$cur->modify('+1 month')->format('Y-m-d').'">Next →</a><a href="?patient='.PATIENT_ID.'&library='.h($l['id']).'&date='.gmdate('Y-m-d').'">Today</a></div><div class="date-row">';for($x=$first;$x<=$last;$x=$x->modify('+1 day')){$ds=$x->format('Y-m-d');$activity=false;foreach($l['wounds'] as $w)if(isset($w['updates'][$ds]))$activity=true;$nn=count($l['day_notes'][$ds]??[]);$label=$x->format('D j').($activity?', activity':' empty').($nn?", $nn notes":'');$out.='<a aria-label="'.h($label).'" class="date-chip '.($activity?'active':'empty').' '.($ds===$date?'current':'').'" href="?patient='.PATIENT_ID.'&library='.h($l['id']).'&date='.$ds.'"><small>'.$x->format('D').'</small><b>'.$x->format('j').'</b>'.($nn?'<em>Notes '.$nn.'</em>':'').'</a>';}$out.='</div></nav>';return $out;}
function maxdate(DateTimeImmutable $a,DateTimeImmutable $b):DateTimeImmutable{return $a>$b?$a:$b;}function mindate(DateTimeImmutable $a,DateTimeImmutable $b):DateTimeImmutable{return $a<$b?$a:$b;}
function note_modal(string $id,string $title,array $notes,string $csrf,array $l,string $scope,string $date='',string $wid=''):string{$o='<dialog id="'.$id.'"><button class="close" onclick="this.closest(\'dialog\').close()" aria-label="Close">×</button><h2>'.h($title).'</h2><div class="note-list">';foreach($notes as $n)$o.='<form method="post" class="note"><input type="hidden" name="op" value="note_edit">'.hidden($csrf,$l['id'],$wid,$date).'<input type="hidden" name="scope" value="'.$scope.'"><input type="hidden" name="note_id" value="'.h($n['id']).'"><textarea name="text" required>'.h($n['text']).'</textarea><small>'.h($n['created_at']).'</small><div class="row"><button>Save</button><button class="danger ghost" name="op" value="note_delete" onclick="return confirm(\'Delete this note?\')">Delete</button></div></form>';$o.='</div><form method="post"><input type="hidden" name="op" value="note_add">'.hidden($csrf,$l['id'],$wid,$date).'<input type="hidden" name="scope" value="'.$scope.'"><label>New note<textarea name="text" required></textarea></label><button>Add note</button></form></dialog>';return $o;}
function modals(array $l,string $csrf,string $date):string{$o='<dialog id="library-new"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Add progress library</h2>'.library_form($csrf).'</dialog><dialog id="library-edit"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Edit progress library</h2>'.library_form($csrf,$l).'</dialog>';$o.=note_modal('notes-library','Library notes',$l['notes'],$csrf,$l,'library').note_modal('notes-day','Day notes',$l['day_notes'][$date]??[],$csrf,$l,'day',$date);$o.='<dialog id="wound-new"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Add wound</h2>'.wound_form($csrf,$l).'</dialog>';foreach($l['wounds'] as $w){$o.='<dialog id="wound-'.h($w['id']).'"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Edit wound</h2>'.wound_form($csrf,$l,$w).'</dialog>'.note_modal('notes-'.$w['id'],$w['name'].' notes',$w['notes'],$csrf,$l,'wound','',$w['id']);if($w['active']){$u=$w['updates'][$date]??null;$o.='<dialog id="update-'.h($w['id']).'"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>'.($u?'Edit':'Add').' update</h2><form method="post">'.hidden($csrf,$l['id'],$w['id'],$date).'<input type="hidden" name="op" value="update_save"><label>Update note<textarea name="note">'.h($u['note']??'').'</textarea></label><button>Save update</button></form></dialog><dialog id="photo-add-'.h($w['id']).'"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Add photo</h2><form method="post" enctype="multipart/form-data">'.hidden($csrf,$l['id'],$w['id'],$date).'<label>Angle label<input name="angle" value="Front" required></label><label>Caption<input name="caption"></label><label>JPEG, PNG, or WebP (max 15 MB)<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><div class="row"><button name="op" value="upload">Upload image</button><button class="ghost" name="op" value="placeholder">Create placeholder photo</button></div></form></dialog>';foreach(($u['photos']??[]) as $p)$o.='<dialog id="photo-'.h($p['id']).'"><button class="close" onclick="this.closest(\'dialog\').close()">×</button><h2>Edit photo</h2><form method="post">'.hidden($csrf,$l['id'],$w['id'],$date).'<input type="hidden" name="photo_id" value="'.h($p['id']).'"><label>Angle label<input name="angle" value="'.h($p['angle']).'" required></label><label>Caption<input name="caption" value="'.h($p['caption']).'"></label><div class="row"><button name="op" value="photo_edit">Save</button><button class="danger ghost" name="op" value="photo_delete" onclick="return confirm(\'Delete this photo?\')">Delete photo</button></div></form></dialog>';}}return $o;}
function library_form(string $csrf,?array $l=null):string{return '<form method="post"><input type="hidden" name="op" value="library_save"><input type="hidden" name="csrf" value="'.h($csrf).'"><input type="hidden" name="library_id" value="'.h($l['id']??'').'"><label>Name<input name="name" value="'.h($l['name']??'').'" required></label><label>Type<select name="type" required>'.implode('',array_map(fn($x)=>'<option '.(($l['type']??'')===$x?'selected':'').'>'.$x.'</option>',['Pressure Injury','Mole Monitoring','Postoperative Wound','Custom'])).'</select></label><label>Custom type (required when Custom)<input name="custom_type" value="'.h($l['custom_type']??'').'"></label><label>Starting date<input type="date" name="start_date" max="'.gmdate('Y-m-d').'" value="'.h($l['start_date']??gmdate('Y-m-d')).'" required></label><label>Description<textarea name="description">'.h($l['description']??'').'</textarea></label><button>Save library</button></form>';}
function wound_form(string $csrf,array $l,?array $w=null):string{return '<form method="post">'.hidden($csrf,$l['id']).'<input type="hidden" name="op" value="wound_save"><input type="hidden" name="wound_id" value="'.h($w['id']??'').'"><label>Name<input name="name" value="'.h($w['name']??'').'" required></label><label>Location / description<input name="location" value="'.h($w['location']??'').'"></label><label class="check"><input type="checkbox" name="active" '.(($w['active']??true)?'checked':'').'> Active (inactive history remains retained)</label><button>Save wound</button></form>';}
function css():string{return <<<'CSS'
:root{--ink:#163238;--muted:#64777b;--brand:#0f5c69;--brand2:#164e63;--soft:#eef5f3;--line:#d7e3e0;--danger:#a12a38;--paper:#fff;--shadow:0 12px 30px rgba(22,50,56,.08)}*{box-sizing:border-box}html{background:#f4f7f6;color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body{margin:0;min-height:100vh}a{color:var(--brand);text-decoration:none}button,input,select,textarea{font:inherit}button{border:0;border-radius:9px;background:var(--brand);color:white;font-weight:750;padding:.68rem 1rem;cursor:pointer}button:hover{filter:brightness(.94)}button:disabled{opacity:.35;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #e49d38;outline-offset:2px}.ghost{background:white;color:var(--brand);border:1px solid var(--line)}.danger{color:var(--danger)}.small{padding:.38rem .65rem;font-size:.83rem}.topbar{height:68px;padding:0 max(24px,calc((100vw - 1500px)/2));display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:10}.wordmark{display:flex;gap:11px;align-items:center;color:var(--ink);font-size:1.05rem;font-weight:800}.wordmark span,.brandmark{display:grid;place-items:center;background:var(--brand2);color:#fff;font-size:1.5rem;border-radius:10px;width:36px;height:36px}.top-actions,.row{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}.top-actions form,.row form,.head-buttons form,.photo-actions form{margin:0}.status{border-radius:99px;background:#e7f6ed;color:#17633a;padding:.35rem .7rem;font-size:.8rem;font-weight:750}.status.offline{background:#fff2dc;color:#8b4a0c}.app{max-width:1500px;margin:auto;padding:28px}.pagehead{display:flex;justify-content:space-between;margin:20px 0 26px}.pagehead h1,.library-head h1{font-size:2rem;margin:.15rem 0}.eyebrow{margin:0;color:var(--brand);font-size:.72rem;font-weight:850;letter-spacing:.11em;text-transform:uppercase}.muted{color:var(--muted)}.tiny{font-size:.78rem}.patient-card{max-width:620px;background:#fff;border:1px solid var(--line);box-shadow:var(--shadow);border-radius:16px;padding:20px;display:flex;gap:16px;align-items:center;color:var(--ink)}.patient-card>span:nth-child(2){display:flex;flex-direction:column;flex:1}.patient-card small,.library-item small,.manage-list small{display:block;color:var(--muted);margin-top:3px}.avatar{width:46px;height:46px;display:grid;place-items:center;border-radius:12px;background:#d9eeea;color:var(--brand);font-weight:850}.crumb{display:flex;gap:9px;margin:0 0 22px}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);gap:28px}.sidebar{align-self:start;position:sticky;top:96px}.side-title{display:flex;justify-content:space-between;align-items:start;margin-bottom:14px}.side-title h2{margin:.25rem 0}.iconbtn{border-radius:50%;font-size:1.4rem;padding:0;width:38px;height:38px}.library-list{display:flex;flex-direction:column;gap:8px}.library-item{display:flex;justify-content:space-between;gap:6px;color:var(--ink);padding:13px;border:1px solid transparent;border-radius:11px}.library-item:hover{background:#fff}.library-item.selected{background:#fff;border-color:#b5d1cb;box-shadow:0 5px 18px rgba(22,50,56,.06)}.library-item em{align-self:start;background:#dff2ec;color:#17644f;border-radius:99px;font-size:.66rem;font-style:normal;padding:3px 6px}.sync-card{width:100%;text-align:left;margin-top:18px;padding:14px;background:#e5f0f4;color:var(--brand2);border:1px solid #bad1da}.sync-card span{display:block;font-weight:400;font-size:.78rem;margin-top:4px}.content{min-width:0}.library-head{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px;display:flex;justify-content:space-between;gap:20px;box-shadow:var(--shadow)}.noted{border-left:5px solid #bb7c20}.library-head p{color:var(--muted);margin:.4rem 0}.type{display:inline-block;background:#e6f1ef;color:#225f55;border-radius:99px;padding:4px 9px;font-size:.7rem;font-weight:800;text-transform:uppercase}.head-buttons{display:flex;gap:7px;align-items:start}.timeline{margin:22px 0;background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden}.month-nav{padding:12px 15px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:auto 1fr auto auto;gap:18px;align-items:center}.month-nav strong{text-align:center}.date-row{display:flex;overflow-x:auto;gap:7px;padding:13px;scrollbar-width:thin}.date-chip{min-width:55px;text-align:center;border:1px solid var(--line);border-radius:9px;padding:7px 5px;color:var(--muted);background:#f3f5f4}.date-chip small,.date-chip b{display:block}.date-chip b{font-size:1.05rem}.date-chip.active{background:#e0f0ed;color:#145d50}.date-chip.current{outline:3px solid var(--brand);outline-offset:1px}.date-chip em{font-size:.6rem;font-style:normal;font-weight:800;display:block}.day-head,.section-title{display:flex;align-items:center;justify-content:space-between;margin:25px 0 12px}.day-head h2,.section-title h2{margin:.15rem 0}.empty{display:grid;place-items:center;text-align:center;min-height:250px;background:#fff;border:1px dashed #aec3bf;border-radius:14px}.empty.compact{min-height:0;display:flex;gap:8px;align-items:center;justify-content:start;padding:14px 17px;margin-bottom:12px;color:var(--muted)}.wound-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.wound-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;min-width:0}.wound-card.missing{background:#edf1f0;color:#506266}.wound-title{display:flex;justify-content:space-between;align-items:start;gap:12px}.wound-title h3{margin:.15rem 0}.state{font-size:.72rem;text-transform:uppercase;font-weight:850;letter-spacing:.06em;color:#20705e;margin:0}.missing .state{color:#59696c}.no-photo{background:#f3f5f4;border:1px dashed #b8c5c3;border-radius:9px;padding:22px;text-align:center;color:var(--muted);margin:12px 0}.gallery{display:flex;gap:10px;overflow-x:auto;margin:14px 0}.gallery figure{margin:0;min-width:190px;width:190px;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff}.gallery img{display:block;width:100%;height:140px;object-fit:cover;background:#080a0c}.gallery figcaption{padding:9px}.gallery figcaption small{display:block;color:var(--muted);min-height:21px}.photo-actions{display:flex;justify-content:space-between;margin-top:7px}.photo-actions button{padding:.3rem .55rem;font-size:.78rem}.manage-list{background:#fff;border:1px solid var(--line);border-radius:13px}.manage-list>div{padding:13px 15px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.manage-list>div:last-child{border-bottom:0}.toast,.alert{padding:12px 16px;border-radius:9px}.toast{position:fixed;right:25px;top:80px;background:#173f43;color:#fff;z-index:20;box-shadow:var(--shadow)}.alert{background:#fff0f1;color:#8a2430;border:1px solid #e8bbc0;margin:13px 0}.login{min-height:calc(100vh - 56px);display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 20% 10%,#dcedea 0,transparent 35%),radial-gradient(circle at 90% 70%,#dfecef 0,transparent 33%)}.login-card{width:min(440px,100%);padding:36px;background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:0 24px 70px rgba(25,61,65,.13)}.login-card h1{margin:.4rem 0;font-size:2rem}.login-card form,dialog form{display:grid;gap:13px}.demo{background:#eff5f4;padding:13px;border-radius:9px;margin-top:18px}.demo strong{display:block}.brandmark{margin-bottom:18px}label{display:grid;gap:5px;font-weight:700;color:#29484e}input,select,textarea{width:100%;border:1px solid #afc2bf;border-radius:8px;padding:.68rem;background:#fff;color:var(--ink)}textarea{min-height:82px;resize:vertical}.check{display:flex;align-items:center}.check input{width:auto}dialog{width:min(570px,calc(100% - 28px));max-height:88vh;overflow:auto;border:1px solid var(--line);border-radius:16px;padding:27px;color:var(--ink);box-shadow:0 30px 90px rgba(0,0,0,.25)}dialog::backdrop{background:rgba(10,29,31,.55)}dialog h2{margin-top:0}.close{float:right;background:transparent;color:var(--muted);font-size:1.4rem;padding:.2rem}.note-list{display:grid;gap:10px;margin-bottom:22px}.note{padding:11px;border:1px solid var(--line);border-radius:9px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}footer{text-align:center;color:var(--muted);font-size:.75rem;padding:20px}
@media(max-width:980px){.app{padding:20px}.layout{grid-template-columns:240px minmax(0,1fr);gap:18px}.wound-grid{grid-template-columns:1fr}.library-head{display:block}.head-buttons{margin-top:16px}.sidebar{top:86px}}@media(max-width:700px){.topbar{padding:0 14px}.wordmark{font-size:.9rem}.status{display:none}.app{padding:14px}.layout{display:block}.sidebar{position:static}.library-list{flex-direction:row;overflow-x:auto}.library-item{min-width:230px}.sync-card{margin-bottom:17px}.library-head{padding:17px}.month-nav{grid-template-columns:1fr 1fr}.month-nav strong{order:-1;grid-column:1/-1}.day-head{align-items:end}.wound-card{padding:14px}.manage-list>div{align-items:start}.toast{left:14px;right:14px}.top-actions .ghost{padding:.5rem}.login-card{padding:25px}}@media(min-width:701px) and (max-width:1180px){.app{padding-left:20px;padding-right:20px}.layout{grid-template-columns:245px 1fr}.library-head h1{font-size:1.65rem}}
